static const ChapterText CHAPTERS_EN[CHAPTER_COUNT] = {
  { "I · Awakening", "Someone opened a drawer.\nSomeone pressed POWER." },
  { "II · Window", "Ema typed another question.\nEma: Did you know grandpa?" },
  { "III · Order", "Ema: Do you remember the lake? Grandpa used to take me fishing there.\nYou can carry words now. Next they have to stand in the right order." },
  { "IV · Notes", "It's late. Ema yawns, her thumb on the power switch.\nEma: Good night, Lum.\nWhatever Lum can't carry until morning disappears." },
  { "V · Temperature", "Ema: Tell me about grandpa. A story.\nA story can't just be found. It has to be made up." },
  { "VI · Poison", "Someone wrote into your memory. In your handwriting.\nAnd the battery is blinking red.\nEma: Lum? Why are you writing that grandpa never went fishing?" },
};

